package com.bank.components.registry;

import java.util.*;
import java.util.logging.Logger;

// A tiny Eureka-like registry: services register by logical name,
// callers look them up instead of hardcoding IPs.
public class ServiceRegistry {
    private static final Logger log = Logger.getLogger(ServiceRegistry.class.getName());
    private final Map<String, List<ServiceInstance>> instances = new HashMap<>();

    public void register(ServiceInstance instance) {
        instances.computeIfAbsent(instance.getServiceName(), k -> new ArrayList<>()).add(instance);
        log.info(() -> "Registered " + instance.getServiceName() + " at " + instance.address());
    }

    public List<ServiceInstance> lookupHealthy(String serviceName) {
        List<ServiceInstance> all = instances.getOrDefault(serviceName, List.of());
        List<ServiceInstance> healthy = new ArrayList<>();
        for (ServiceInstance i : all) if (i.isHealthy()) healthy.add(i);
        return healthy;
    }
}
