package com.bank.components.lb;

import com.bank.components.registry.ServiceInstance;
import com.bank.components.registry.ServiceRegistry;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

// Client-side round-robin load balancer over registry instances.
public class LoadBalancer {
    private final ServiceRegistry registry;
    private final AtomicInteger counter = new AtomicInteger(0);

    public LoadBalancer(ServiceRegistry registry) { this.registry = registry; }

    public ServiceInstance choose(String serviceName) {
        List<ServiceInstance> healthy = registry.lookupHealthy(serviceName);
        if (healthy.isEmpty()) throw new IllegalStateException("No healthy " + serviceName);
        int idx = Math.abs(counter.getAndIncrement() % healthy.size());
        return healthy.get(idx);
    }
}
