package com.bank.components.client;

import com.bank.components.config.ConfigServer;
import com.bank.components.lb.LoadBalancer;
import com.bank.components.registry.ServiceInstance;
import java.math.BigDecimal;
import java.util.logging.Logger;

// Resolves "account-service" through the registry + load balancer,
// reads its timeout from the Config Server, and would wrap the call
// in a circuit breaker in real Spring code.
public class AccountClient {
    private static final Logger log = Logger.getLogger(AccountClient.class.getName());
    private final LoadBalancer loadBalancer;
    private final ConfigServer configServer;

    public AccountClient(LoadBalancer loadBalancer, ConfigServer configServer) {
        this.loadBalancer = loadBalancer;
        this.configServer = configServer;
    }

    // @CircuitBreaker(name="accountService", fallbackMethod="debitFallback")
    public void debit(String accountId, BigDecimal amount) {
        ServiceInstance instance = loadBalancer.choose("account-service");
        String timeout = configServer.get("account.debit.timeout-ms");
        log.info(() -> "debit " + amount + " from " + accountId
                     + " via " + instance.address() + " (timeout=" + timeout + "ms)");
    }
}
