package com.bank.components;

import com.bank.components.client.AccountClient;
import com.bank.components.config.ConfigServer;
import com.bank.components.lb.LoadBalancer;
import com.bank.components.registry.ServiceInstance;
import com.bank.components.registry.ServiceRegistry;
import java.math.BigDecimal;
import java.util.logging.Logger;

public class ComponentsDemo {
    private static final Logger log = Logger.getLogger(ComponentsDemo.class.getName());

    public static void main(String[] args) {
        ServiceRegistry registry = new ServiceRegistry();
        registry.register(new ServiceInstance("account-service", "10.0.0.1", 8082));
        registry.register(new ServiceInstance("account-service", "10.0.0.2", 8082));
        ServiceInstance down = new ServiceInstance("account-service", "10.0.0.3", 8082);
        registry.register(down);

        LoadBalancer lb = new LoadBalancer(registry);
        ConfigServer config = new ConfigServer();
        AccountClient client = new AccountClient(lb, config);
        BigDecimal rentAmount = new BigDecimal("50000");

        log.info("=== Traffic spread across 3 instances ===");
        for (int i = 0; i < 4; i++) client.debit("SAV2001", rentAmount);

        log.info("=== One instance goes down, failover ===");
        down.setHealthy(false);
        for (int i = 0; i < 3; i++) client.debit("SAV2001", rentAmount);
    }
}
